const breakLine = (text: string) => {
  const arr = text.split(' ');
  const len1 = Math.floor(arr.length / 2);
  console.log('arr', arr, len1);

  const line1 = arr.slice(0, len1).join(' ');
  const line2 = arr.slice(len1).join(' ');

  return [line1, line2];
};

